  protected override void Initialize() {
    this.InitSpecialTokens((int)Tokens.error, (int)Tokens.EOF);
    this.InitStates(states);
    this.InitRules(rules);
    this.InitNonTerminals(nonTerms);
  }

  protected override void DoAction(int action)
  {
    switch (action)
    {
      case 2: // program -> import_clause, decl_and_stmt_list, optional_semicolon
{
		var ul = ValueStack[ValueStack.Depth-3].stn as uses_list;
		var stl = ValueStack[ValueStack.Depth-2].stn as statement_list;
		stl.left_logical_bracket = new token_info("");
		stl.right_logical_bracket = new token_info("");
		var bl = new block(decl, stl, LocationStack[LocationStack.Depth-2]);
		decl.AddFirst(decl_forward.defs);
		root = CurrentSemanticValue.stn = NewProgramModule(null, null, ul, bl, ValueStack[ValueStack.Depth-1].ob, CurrentLocationSpan);
		root.source_context = bl.source_context;
	}
        break;
      case 3: // program -> MOD, ident, SEMICOLON, import_clause, decl_and_stmt_list
{
		decl.AddFirst(decl_forward.defs);
		var interface_part = new interface_node(decl as declarations, ValueStack[ValueStack.Depth-2].stn as uses_list, null, null);
		var initialization_part = new initfinal_part(null, ValueStack[ValueStack.Depth-1].stn as statement_list, null, null, null, CurrentLocationSpan);

		root = CurrentSemanticValue.stn = new unit_module(
			new unit_name(new ident(ValueStack[ValueStack.Depth-4].id.name),
			UnitHeaderKeyword.Unit, CurrentLocationSpan), interface_part, null,
			initialization_part.initialization_sect,
			initialization_part.finalization_sect, null, CurrentLocationSpan);
	}
        break;
      case 4: // program -> task_list
{
                var stl = ValueStack[ValueStack.Depth-1].stn as statement_list;
                root = NewProgramModule(null, null, null, new block(null, stl, CurrentLocationSpan), null, CurrentLocationSpan);
            }
        break;
      case 5: // task_list -> /* empty */
{
        CurrentSemanticValue.stn = new statement_list();
    }
        break;
      case 6: // task_list -> task_list, task_decl
{
        (ValueStack[ValueStack.Depth-2].stn as statement_list).Add(ValueStack[ValueStack.Depth-1].stn as statement, CurrentLocationSpan);
        CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
    }
        break;
      case 7: // task_decl -> TASK, STRINGNUM, LBRACE, task_body, RBRACE
{
        var taskName = (ValueStack[ValueStack.Depth-4].stn as literal)?.ToString(); 
	var bodyStmts = ValueStack[ValueStack.Depth-2].stn as statement_list; 

	var stl = new statement_list();
	
	// Созда�?м blockStmt, �?�?об�? �?пакова�?�? bodyStmts в block
	var blockStmt = new block(null, bodyStmts, CurrentLocationSpan);

	// �?�?и�?и�?еская �?ас�?�?: 
	for (int i = 2; i < blockStmt.subnodes_count; i++)
        {
            var st = blockStmt[i] as statement;
            if (st != null)
                stl.subnodes.Add(st);
        }

	CurrentSemanticValue.stn = stl;
    }
        break;
      case 8: // task_body -> input_section, solution_section, tests_section, output_section
{
        var stl = new statement_list();
        if (ValueStack[ValueStack.Depth-4].stn != null) stl.subnodes.Add(ValueStack[ValueStack.Depth-4].stn as statement);
        if (ValueStack[ValueStack.Depth-3].stn != null) stl.subnodes.Add(ValueStack[ValueStack.Depth-3].stn as statement);
        if (ValueStack[ValueStack.Depth-2].stn != null) stl.subnodes.Add(ValueStack[ValueStack.Depth-2].stn as statement);
        if (ValueStack[ValueStack.Depth-1].stn != null) stl.subnodes.Add(ValueStack[ValueStack.Depth-1].stn as statement);
        CurrentSemanticValue.stn = stl;
    }
        break;
      case 9: // input_section -> INPUT, LBRACE, stmt_list, RBRACE
{
        CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
    }
        break;
      case 10: // input_section -> /* empty */
{
        CurrentSemanticValue.stn = null;
    }
        break;
      case 11: // solution_section -> SOLUTION, LBRACE, stmt_list, RBRACE
{
        CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
    }
        break;
      case 12: // solution_section -> /* empty */
{
        CurrentSemanticValue.stn = null;
    }
        break;
      case 13: // tests_section -> TESTS, LBRACE, stmt_list, RBRACE
{
        CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
    }
        break;
      case 14: // tests_section -> /* empty */
{
        CurrentSemanticValue.stn = null;
    }
        break;
      case 15: // output_section -> OUTPUT, LBRACE, stmt_list, RBRACE
{
        CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
    }
        break;
      case 16: // output_section -> /* empty */
{
        CurrentSemanticValue.stn = null;
    }
        break;
      case 17: // import_clause -> /* empty */
{ CurrentSemanticValue.stn = null; }
        break;
      case 18: // import_clause -> import_clause, import_clause_one
{
		if (parserTools.build_tree_for_formatter) {
			if (ValueStack[ValueStack.Depth-2].stn == null) {	
				CurrentSemanticValue.stn = new uses_closure(ValueStack[ValueStack.Depth-1].stn as uses_list,CurrentLocationSpan);
			} else {
			    (ValueStack[ValueStack.Depth-2].stn as uses_closure).AddUsesList(ValueStack[ValueStack.Depth-1].stn as uses_list,CurrentLocationSpan);
			    CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
			}
		} else {
			if (ValueStack[ValueStack.Depth-2].stn == null) {
			    CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn;
			    CurrentSemanticValue.stn.source_context = CurrentLocationSpan;
			} else {
			    (ValueStack[ValueStack.Depth-2].stn as uses_list).AddUsesList(ValueStack[ValueStack.Depth-1].stn as uses_list,CurrentLocationSpan);
			    CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
			    CurrentSemanticValue.stn.source_context = CurrentLocationSpan;
			}
		}
		}
        break;
